-- top payees of the 19 (copies dropped), vendor name normalised (no punctuation, no spaces, no LLC/INC suffix), with payee city/state and purposes
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
f AS (SELECT b.EIN, REGEXP_REPLACE(REGEXP_REPLACE(UPPER(RECIPIENT_NAME),'[^A-Z0-9]',''),'(LLC|INC|CORP|CORPORATION|CO|LTD|LP)$','') v, EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, FORM_ID_NUMBER, COUNT(*) n,
   ANY_VALUE(UPPER(RECIPIENT_CITY)||' '||RECIPIENT_STATE) loc, ANY_VALUE(LEFT(UPPER(EXPENDITURE_PURPOSE),40)) p
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES b JOIN g ON g.EIN=b.EIN GROUP BY 1,2,3,4,5),
k AS (SELECT EIN, v, d, a, MAX(n) n, ANY_VALUE(loc) loc, ANY_VALUE(p) p FROM f GROUP BY 1,2,3,4)
SELECT v, ROUND(SUM(n*a)/1e6,2) amt_m, COUNT(DISTINCT EIN) groups19, MIN(d) first_d, MAX(d) last_d,
  LISTAGG(DISTINCT loc, ' / ') WITHIN GROUP (ORDER BY loc) locs, LEFT(LISTAGG(DISTINCT p, ' / '),200) purposes,
  ROUND(100*SUM(n*a)/SUM(SUM(n*a)) OVER (),1) pct_of_19
FROM k GROUP BY v ORDER BY amt_m DESC LIMIT 30
